#include <stdio.h>
#include <stdlib.h>

int main() {
    int n = 5;
    int *evens = calloc(n, sizeof(int));
    for (int i = 0; i < n; i++) {
        evens[i] = 2 * (i + 1);
    }
    for (int i = 0; i < n; i++) printf("%d ", evens[i]);
    printf("\n");
    free(evens);
    return 0;
}
